UPDATE public.tasks
SET title = 'Путь солдата',
    description = 'Для проведения комплексного аудита материально-технического обеспечения выведите список выданного снаряжения с привязкой к бойцу и его воинской части. Выведите полное имя солдата (full_name), название подразделения (unit_name), наименование снаряжения (item_name), выданное количество (quantity) и дату выдачи (issue_date). Отсортируйте результат по ФИО солдата, а затем по дате выдачи.',
    clue = 'Используйте цепочку INNER JOIN для 5 таблиц: soldier -> military_service -> military_unit, а также soldier -> equipment_assignment -> equipment.',
    correct_query = 'SELECT s.full_name, u.unit_name, e.item_name, ea.quantity, ea.issue_date
FROM soldier s
JOIN military_service ms ON s.id = ms.soldier_id
JOIN military_unit u ON ms.unit_id = u.id
JOIN equipment_assignment ea ON s.id = ea.soldier_id
JOIN equipment e ON ea.equipment_id = e.id
ORDER BY s.full_name, ea.issue_date;',
    expected_result = '{"columns": ["full_name", "unit_name", "item_name", "quantity", "issue_date"], "data": [["Васнецова Татьяна Дмитриевна", "106-я стрелковая дивизия", "ПТРД", 1, "1944-03-01"], ["Громов Михаил Сергеевич", "2-я ударная армия", "Сапёрная лопатка", 1, "1943-08-15"], ["Жуков Андрей Григорьевич", "16-я воздушная армия", "Ил-2", 1, "1943-05-05"], ["Зайцева Людмила Михайловна", "150-я стрелковая дивизия", "БМ-13 \"Катюша\"", 120, "1944-01-20"], ["Иванов Алексей Петрович", "316-я стрелковая дивизия", "Винтовка Мосина", 1, "1942-03-02"], ["Иванов Алексей Петрович", "316-я стрелковая дивизия", "Патроны 7.62 мм", 120, "1942-03-02"], ["Козлов Николай Семёнович", "1-я гвардейская танковая армия", "Т-34", 1, "1943-07-10"], ["Кузнецов Пётр Васильевич", "1-я гвардейская танковая армия", "Радиостанция РБМ", 1, "1942-05-12"], ["Новиков Александр Иванович", "3-я воздушная армия", "ФАБ-100", 24, "1943-09-06"], ["Орлова Вера Павловна", "8-я гвардейская армия", "ИС-2", 1, "1944-10-02"], ["Павлов Яков Фёдорович", "62-я армия", "76-мм дивизионная пушка ЗИС-3", 1, "1942-11-15"], ["Смирнова Анна Васильевна", "62-я армия", "Аптечки полевые", 5, "1943-01-12"], ["Соколова Ольга Ивановна", "16-я воздушная армия", "Плазменные флаконы", 3, "1943-12-05"]], "row_count": 13}'::jsonb,
    tags = ARRAY['join', 'medium']::varchar[]
WHERE task_global_id = 70;

UPDATE public.tasks
SET title = 'Накопление резервов призыва',
    description = 'Для оценки темпов мобилизации рассчитайте общее количество призывников по годам и нарастающий итог призыва по годам. Выведите год призыва (year), число призванных в этом году (yearly_enlisted) и накопленный итог призыва за все предшествующие и текущий годы (cumulative_enlisted). Отсортируйте по году.',
    clue = 'Используйте оконную агрегацию SUM(COUNT(*)) OVER (ORDER BY EXTRACT(YEAR FROM enlistment_date)) поверх группировки по годам.',
    correct_query = 'SELECT EXTRACT(YEAR FROM enlistment_date)::int AS year,
       COUNT(*) AS yearly_enlisted,
       SUM(COUNT(*)) OVER (ORDER BY EXTRACT(YEAR FROM enlistment_date))::int AS cumulative_enlisted
FROM soldier
GROUP BY EXTRACT(YEAR FROM enlistment_date)
ORDER BY year;',
    expected_result = '{"columns": ["year", "yearly_enlisted", "cumulative_enlisted"], "data": [[1941, 13, 13], [1942, 10, 23], [1943, 11, 34], [1944, 6, 40]], "row_count": 4}'::jsonb,
    tags = ARRAY['window', 'aggregation', 'medium']::varchar[]
WHERE task_global_id = 46;

UPDATE public.tasks
SET title = 'Годовая динамика ранений',
    description = 'Проанализируйте динамику ранений бойцов по годам окончания службы. С помощью CTE определите год окончания службы (year) и количество раненых солдат (wounded_count, статус «ранен»), а затем с помощью оконной функции рассчитайте общее среднее число раненых в год (avg_wounded, округлите до 2 знаков). Отсортируйте результат по году.',
    clue = 'Сначала сформируйте CTE с группировкой раненых бойцов по годам ms.end_date, затем примените ROUND(AVG(wounded_count) OVER (), 2)::float в основном запросе.',
    correct_query = 'WITH yearly_wounded AS (
    SELECT EXTRACT(YEAR FROM ms.end_date)::int AS year,
           COUNT(*) AS wounded_count
    FROM soldier s
    JOIN military_service ms ON s.id = ms.soldier_id
    WHERE s.status = ''ранен'' AND ms.end_date IS NOT NULL
    GROUP BY EXTRACT(YEAR FROM ms.end_date)
)
SELECT year,
       wounded_count,
       ROUND(AVG(wounded_count) OVER (), 2)::float AS avg_wounded
FROM yearly_wounded
ORDER BY year;',
    expected_result = '{"columns": ["year", "wounded_count", "avg_wounded"], "data": [[1943, 3, 2.33], [1944, 3, 2.33], [1945, 1, 2.33]], "row_count": 3}'::jsonb,
    tags = ARRAY['cte', 'window', 'medium']::varchar[]
WHERE task_global_id = 48;

UPDATE public.tasks
SET title = 'Силы противника на Курской дуге',
    description = 'Определите подразделения противника, принимавшие участие в сражении на Курской дуге. Для этого с помощью CTE найдите идентификатор битвы, содержащей в названии «Курск», соедините таблицы enemy_unit и battle_enemy_unit и выведите наименования частей противника (unit_name). Отсортируйте по названию части.',
    clue = 'Используйте CTE для поиска битвы Курской дуги по названию (battle_name ILIKE ''%Курск%'') и свяжите с battle_enemy_unit и enemy_unit.',
    correct_query = 'WITH target_battle AS (
    SELECT id FROM battle WHERE battle_name ILIKE ''%Курск%''
)
SELECT eu.unit_name
FROM enemy_unit eu
JOIN battle_enemy_unit beu ON eu.id = beu.enemy_unit_id
WHERE beu.battle_id IN (SELECT id FROM target_battle)
ORDER BY eu.unit_name;',
    expected_result = '{"columns": ["unit_name"], "data": [["12-я танковая дивизия"], ["337-я пехотная дивизия"], ["503-й тяжёлый танковый батальон"], ["505-й инженерный батальон"], ["505-й тяжёлый танковый батальон"], ["Танковая группа \"Кемпф\""], ["Эскадра KG27 \"Бёльке\""], ["Эскадра SG2 \"Иммельман\""]], "row_count": 8}'::jsonb,
    tags = ARRAY['cte', 'join', 'medium']::varchar[]
WHERE task_global_id = 50;

UPDATE public.tasks
SET title = 'Категории потерь под Сталинградом',
    description = 'Оцените потери советских войск в Сталинградской битве (с 17 июля 1942 по 2 февраля 1943 года). С помощью CTE выделите бойцов, проходивших службу в этот период, разделите потери на две категории: «Безвозвратные потери» (статус «убит» или «пропал без вести») и «Санитарные потери» (статус «ранен»), и объедините результаты через UNION ALL. Выведите категорию потерь (loss_category) и число солдат (soldiers_count).',
    clue = 'Используйте CTE для выборки солдат, служивших в период Сталинградской битвы, и UNION ALL для объединения двух веток подсчёта.',
    correct_query = 'WITH stalingrad_soldiers AS (
    SELECT s.id, s.status
    FROM soldier s
    JOIN military_service ms ON s.id = ms.soldier_id
    WHERE ms.start_date <= ''1943-02-02''
      AND (ms.end_date IS NULL OR ms.end_date >= ''1942-07-17'')
),
irrecoverable AS (
    SELECT ''Безвозвратные потери'' AS loss_category, COUNT(*) AS soldiers_count
    FROM stalingrad_soldiers
    WHERE status IN (''убит'', ''пропал без вести'')
),
sanitary AS (
    SELECT ''Санитарные потери'' AS loss_category, COUNT(*) AS soldiers_count
    FROM stalingrad_soldiers
    WHERE status = ''ранен''
)
SELECT loss_category, soldiers_count FROM irrecoverable
UNION ALL
SELECT loss_category, soldiers_count FROM sanitary;',
    expected_result = '{"columns": ["loss_category", "soldiers_count"], "data": [["Безвозвратные потери", 8], ["Санитарные потери", 6]], "row_count": 2}'::jsonb,
    tags = ARRAY['cte', 'union', 'medium']::varchar[]
WHERE task_global_id = 51;

UPDATE public.tasks
SET title = 'Рейтинг эффективности подразделений',
    description = 'Составьте рейтинг боевой эффективности воинских подразделений. Выведите название подразделения (unit_name), показатель боевой эффективности (combat_efficiency), а также два ранга: eff_rank с помощью функции RANK() и eff_dense_rank с помощью функции DENSE_RANK(), упорядоченные по убыванию эффективности. Исключите подразделения с неопределённой эффективностью. Отсортируйте результат по убыванию combat_efficiency, а при равенстве — по unit_name.',
    clue = 'Примените RANK() OVER (ORDER BY combat_efficiency DESC) и DENSE_RANK() OVER (ORDER BY combat_efficiency DESC).',
    correct_query = 'SELECT unit_name,
       combat_efficiency,
       RANK() OVER (ORDER BY combat_efficiency DESC) AS eff_rank,
       DENSE_RANK() OVER (ORDER BY combat_efficiency DESC) AS eff_dense_rank
FROM military_unit
WHERE combat_efficiency IS NOT NULL
ORDER BY combat_efficiency DESC, unit_name;',
    expected_result = '{"columns": ["unit_name", "combat_efficiency", "eff_rank", "eff_dense_rank"], "data": [["8-я гвардейская армия", 98.5, 1, 1], ["150-я стрелковая дивизия", 97.8, 2, 2], ["46-й гвардейский ночной бомбардировочный полк", 96.7, 3, 3], ["37-й гвардейский миномётный полк", 96.5, 4, 4], ["101-й полк НКВД", 96.2, 5, 5], ["1-я гвардейская танковая армия", 95.0, 6, 6], ["585-й женский авиаполк", 94.1, 7, 7], ["64-я стрелковая дивизия", 92.4, 8, 8], ["62-я армия", 92.3, 9, 9], ["Отдельная медико-санитарная рота", 91.7, 10, 10], ["7-я гвардейская миномётная дивизия", 90.5, 11, 11], ["225-й отдельный инженерный батальон", 89.7, 12, 12], ["101-й инженерно-сапёрный батальон", 89.5, 13, 13], ["106-я стрелковая дивизия", 89.3, 14, 14], ["16-я воздушная армия", 88.9, 15, 15], ["369-й отдельный батальон морской пехоты", 88.9, 15, 15], ["18-я дивизия СС \"Хорст Вессель\"", 88.1, 17, 16], ["316-я стрелковая дивизия", 85.5, 18, 17], ["Отдельный батальон связи №45", 85.2, 19, 18], ["1-й отдельный чехословацкий батальон", 85.0, 20, 19], ["3-я воздушная армия", 85.0, 20, 19], ["1-я морская бригада", 82.4, 22, 20], ["Отдельный отряд собак-истребителей танков", 82.4, 22, 20], ["Отдельный отряд собак-миноискателей", 81.3, 24, 21], ["1-й чехословацкий отдельный батальон", 78.5, 25, 22], ["2-я ударная армия", 75.2, 26, 23], ["88-й отдельный лыжный батальон", 73.9, 27, 24], ["28-я дивизия народного ополчения", 69.8, 28, 25], ["101-й учебный полк", 68.3, 29, 26], ["14-я отдельная штрафная рота", 65.8, 30, 27]], "row_count": 30}'::jsonb,
    tags = ARRAY['window', 'ranking', 'medium']::varchar[]
