UPDATE public.tasks
SET title = 'Хронология призыва в подразделения',
    description = 'Для каждого воинского подразделения определите порядок прибытия новобранцев. Выведите наименование подразделения (unit_name), ФИО солдата (full_name), дату начала службы (start_date) и порядковый номер бойца в части (recruit_order), вычисленный с помощью ROW_NUMBER() с разбиением по подразделению и упорядочиванием по дате службы (и s.id при совпадении). Отсортируйте итоговый результат по unit_name и recruit_order.',
    clue = 'Используйте ROW_NUMBER() OVER (PARTITION BY u.id ORDER BY ms.start_date, s.id).',
    correct_query = 'SELECT u.unit_name,
       s.full_name,
       ms.start_date,
       ROW_NUMBER() OVER (PARTITION BY u.id ORDER BY ms.start_date, s.id) AS recruit_order
FROM military_unit u
JOIN military_service ms ON u.id = ms.unit_id
JOIN soldier s ON ms.soldier_id = s.id
ORDER BY u.unit_name, recruit_order;',
    expected_result = '{"columns": ["unit_name", "full_name", "start_date", "recruit_order"], "data": [["1-й отдельный чехословацкий батальон", "Белов Дмитрий Николаевич", "1942-05-25", 1], ["1-й отдельный чехословацкий батальон", "Воронцова Лидия Павловна", "1943-02-01", 2], ["1-й чехословацкий отдельный батальон", "Мельникова Галина Ивановна", "1942-10-01", 1], ["1-я гвардейская танковая армия", "Козлов Николай Семёнович", "1941-09-15", 1], ["1-я гвардейская танковая армия", "Кузнецов Пётр Васильевич", "1941-10-05", 2], ["1-я морская бригада", "Волкова Елена Сергеевна", "1943-09-20", 1], ["101-й инженерно-сапёрный батальон", "Морозова Анна Сергеевна", "1942-07-15", 1], ["101-й инженерно-сапёрный батальон", "Фролов Павел Сергеевич", "1944-06-15", 2], ["101-й полк НКВД", "Семёнова Валентина Михайловна", "1942-11-15", 1], ["101-й учебный полк", "Гришин Алексей Петрович", "1941-07-05", 1], ["106-я стрелковая дивизия", "Васнецова Татьяна Дмитриевна", "1943-11-10", 1], ["14-я отдельная штрафная рота", "Морозов Иван Кузьмич", "1942-08-05", 1], ["150-я стрелковая дивизия", "Зайцева Людмила Михайловна", "1943-02-01", 1], ["150-я стрелковая дивизия", "Белов Алексей Николаевич", "1944-05-01", 2], ["16-я воздушная армия", "Жуков Андрей Григорьевич", "1941-06-25", 1], ["16-я воздушная армия", "Соколова Ольга Ивановна", "1942-06-20", 2], ["18-я дивизия СС \"Хорст Вессель\"", "Жукова Елена Викторовна", "1942-11-15", 1], ["2-я ударная армия", "Громов Михаил Сергеевич", "1942-04-01", 1], ["225-й отдельный инженерный батальон", "Орлов Денис Сергеевич", "1944-08-10", 1], ["28-я дивизия народного ополчения", "Горбачёв Алексей Дмитриевич", "1943-08-01", 1], ["3-я воздушная армия", "Новиков Александр Иванович", "1944-09-01", 1], ["316-я стрелковая дивизия", "Иванов Алексей Петрович", "1941-08-05", 1], ["316-я стрелковая дивизия", "Фёдорова Мария Ивановна", "1943-09-01", 2], ["369-й отдельный батальон морской пехоты", "Ковалёв Сергей Николаевич", "1943-02-15", 1], ["37-й гвардейский мин