UPDATE public.tasks
SET title = 'Циклы снабжения подразделений',
    description = 'Для анализа регулярности поставок снаряжения в части определите предыдущую и следующую даты поступления имущества. Выведите наименование подразделения (unit_name), название снаряжения (item_name), дату текущей поставки (last_replenishment), а также предыдущую дату (prev_replenishment) с помощью LAG() и следующую дату (next_replenishment) с помощью LEAD() с разбиением по подразделению и упорядочиванием по дате поставки и названию предмета. Отсортируйте результат по unit_name, last_replenishment и item_name.',
    clue = 'Примените LAG(e.last_replenishment) и LEAD(e.last_replenishment) с OVER (PARTITION BY u.id ORDER BY e.last_replenishment, e.item_name).',
    correct_query = 'SELECT u.unit_name,
       e.item_name,
       e.last_replenishment,
       LAG(e.last_replenishment) OVER (PARTITION BY u.id ORDER BY e.last_replenishment, e.item_name) AS prev_replenishment,
       LEAD(e.last_replenishment) OVER (PARTITION BY u.id ORDER BY e.last_replenishment, e.item_name) AS next_replenishment
FROM equipment e
JOIN military_unit u ON e.unit_id = u.id
ORDER BY u.unit_name, e.last_replenishment, e.item_name;',
    expected_result = '{"columns": ["unit_name", "item_name", "last_replenishment", "prev_replenishment", "next_replenishment"], "data": [["1-я гвардейская танковая армия", "Т-34", "1943-07-05", null, null], ["1-я морская бригада", "82-мм", "1942-03-05", null, "1942-03-05"], ["1-я морская бригада", "Аптечки полевые", "1942-03-05", "1942-03-05", "1942-06-06"], ["1-я морская бригада", "50-мм", "1942-06-06", "1942-03-05", null], ["106-я стрелковая дивизия", "ПТРД", "1944-02-28", null, null], ["150-я стрелковая дивизия", "БМ-13 \"Катюша\"", "1944-01-15", null, null], ["16-я воздушная армия", "Ил-2", "1943-05-01", null, null], ["2-я ударная армия", "Сапёрная лопатка", "1943-08-14", null, null], ["3-я воздушная армия", "ФАБ-100", "1943-09-05", null, null], ["316-я стрелковая дивизия", "Винтовка Мосина", "1942-03-01", null, "1942-03-05"], ["316-я стрелковая дивизия", "Патроны 7.62 мм", "1942-03-05", "1942-03-01", "1942-05-10"], ["316-я стрелковая дивизия", "Радиостанция РБМ", "1942-05-10", "1942-03-05", null], ["37-й гвардейский миномётный полк", "Патроны 7.62 мм", "1942-03-05", null, null], ["585-й женский авиаполк", "Патроны 7.62 мм", "1942-03-05", null, null], ["62-я армия", "Патроны 7.62 мм", "1942-03-05", null, "1942-11-10"], ["62-я армия", "76-мм дивизионная пушка ЗИС-3", "1942-11-10", "1942-03-05", "1943-01-10"], ["62-я армия", "Аптечки полевые", "1943-01-10", "1942-11-10", "1943-12-01"], ["62-я армия", "Плазменные флаконы", "1943-12-01", "1943-01-10", null], ["64-я стрелковая дивизия", "Патроны 7.62 мм", "1942-03-05", null, null], ["7-я гвардейская миномётная дивизия", "М-31", "1942-12-01", null, "1942-12-01"], ["7-я гвардейская миномётная дивизия", "Патроны 7.62 мм", "1942-12-01", "1942-12-01", null], ["8-я гвардейская армия", "ИС-2", "1944-10-01", null, null], ["Отдельная медико-санитарная рота", "Аптечки полевые", "1942-03-05", null, "1942-03-05"], ["Отдельная медико-санитарная рота", "Патроны 7.62 мм", "1942-03-05", "1942-03-05", null]], "row_count": 24}'::jsonb,
