UPDATE public.tasks
SET title = 'Критический дефицит снаряжения',
    description = 'Для анализа состояния снабжения воинских подразделений необходимо выявить снаряжение, количество которого значительно отклоняется от среднего уровня по каждому типу. Для этого требуется рассчитать среднее количество и стандартное отклонение для каждого типа снаряжения (equipment_type) по всем подразделениям, а затем определить, в каких именно частях и какие конкретно предметы снаряжения находятся в дефиците. Каждая единица снаряжения должна быть классифицирована как «Критический дефицит», если её количество ниже среднего на полторы стандартные девиации (при наличии вариации STDDEV > 0), как «Дефицит», если количество ниже среднего, но не достигает уровня критического дефицита, и как «Норма» в остальных случаях. В результате должен быть выведен список всего снаряжения с указанием его типа (equipment_type), названия (item_name), названия подразделения (unit_name), количества (quantity) и статуса (status), отсортированный по типу снаряжения, возрастанию количества и названию предмета.',
    clue = 'Примените оконные функции AVG(e.quantity) OVER (PARTITION BY e.equipment_type) и STDDEV(e.quantity) OVER (PARTITION BY e.equipment_type) в конструкции CASE.',
    correct_query = 'SELECT e.equipment_type,
       e.item_name,
       mu.unit_name,
       e.quantity,
       CASE
           WHEN STDDEV(e.quantity) OVER (PARTITION BY e.equipment_type) > 0 
                AND e.quantity < AVG(e.quantity) OVER (PARTITION BY e.equipment_type) - 1.5 * STDDEV(e.quantity) OVER (PARTITION BY e.equipment_type) 
           THEN ''Критический дефицит''
           WHEN e.quantity < AVG(e.quantity) OVER (PARTITION BY e.equipment_type) 
           THEN ''Дефицит''
           ELSE ''Норма''
       END AS status
FROM equipment e
LEFT JOIN military_unit mu ON e.unit_id = mu.id
ORDER BY e.equipment_type, e.quantity, e.item_name;',
    expected_result = '{"columns": ["equipment_type", "item_name", "unit_name", "quantity", "status"], "data": [["авиабомбы", "ФАБ-100", "3-я воздушная армия", 3200, "Норма"], ["артиллерия", "76-мм дивизионная пушка ЗИС-3", "62-я армия", 24, "Норма"], ["боеприпасы", "Патроны 7.62 мм", "7-я гвардейская миномётная дивизия", 20000, "Критический дефицит"], ["боеприпасы", "Патроны 7.62 мм", "Отдельная медико-санитарная рота", 30000, "Дефицит"], ["боеприпасы", "Патроны 7.62 мм", "585-й женский авиаполк", 40000, "Дефицит"], ["боеприпасы", "Патроны 7.62 мм", "316-я стрелковая дивизия", 50000, "Норма"], ["боеприпасы", "Патроны 7.62 мм", "37-й гвардейский миномётный полк", 50000, "Норма"], ["боеприпасы", "Патроны 7.62 мм", "62-я армия", 50000, "Норма"], ["боеприпасы", "Патроны 7.62 мм", "64-я стрелковая дивизия", 70000, "Норма"], ["инженерное", "Сапёрная лопатка", "2-я ударная армия", 850, "Норма"], ["медицина", "Аптечки полевые", "1-я морская бригада", 250, "Дефицит"], ["медицина", "Аптечки полевые", "Отдельная медико-санитарная рота", 250, "Дефицит"], ["медицина", "Аптечки полевые", "62-я армия", 350, "Норма"], ["медицина", "Плазменные флаконы", "62-я армия", 480, "Норма"], ["миномёты", "БМ-13 \"Катюша\"", "150-я стрелковая дивизия", 12, "Дефицит"], ["миномёты", "82-мм", "1-я морская бригада", 930, "Норма"], ["миномёты", "50-мм", "1-я морская бригада", 1326, "Норма"], ["оружие", "Винтовка Мосина", "316-я стрелковая дивизия", 1200, "Норма"], ["противотанковые", "ПТРД", "106-я стрелковая дивизия", 68, "Норма"], ["реактивные снаряды", "М-31", "7-я гвардейская миномётная дивизия", 1500, "Норма"], ["самолёты", "Ил-2", "16-я воздушная армия", 45, "Норма"], ["связь", "Радиостанция РБМ", "316-я стрелковая дивизия", 15, "Норма"], ["танки", "ИС-2", "8-я гвардейская армия", 42, "Дефицит"], ["танки", "Т-34", "1-я гвардейская танковая армия", 58, "Норма"]], "row_count": 24}'::jsonb,
    tags = ARRAY['window', 'statistics', 'hard']::varchar[]
WHERE task_global_id = 59;

UPDATE public.tasks
SET title = 'Сезонность боевых действий',
    description = 'Для выявления сезонных закономерностей в боевых действиях проанализируйте все 12 месяцев года. Сгенерируйте календарь месяцев от 1 до 12 с их названиями. Подсчитайте общее количество завершившихся сражений (total_battles по end_date) и долю побед советских войск (win_percentage, округлённую до 1 знака после запятой) для каждого месяца. Победами считаются битвы с исходами, свидетельствующими об успехе СССР (содержащими корни «побед», «успеш», «освобожд», «разгром», «взятие», «капитуляц» и не относящимися к победам вермахта). Если в месяце не было боев, выведите 0 боев и 0.0% побед. Выведите month_num, month_name, total_battles, win_percentage с сортировкой по номеру месяца.',
    clue = 'Используйте generate_series(1, 12) для создания сетки месяцев и объедините через LEFT JOIN с группировкой битв по EXTRACT(MONTH FROM end_date).',
    correct_query = 'WITH all_months AS (
    SELECT m AS month_num,
           TRIM(TO_CHAR(TO_DATE(m::text, ''MM''), ''Month'')) AS month_name
    FROM generate_series(1, 12) m
),
monthly_battles AS (
    SELECT EXTRACT(MONTH FROM end_date)::int AS month_num,
           COUNT(*) AS total_battles,
           COUNT(*) FILTER (WHERE result ~* ''(побед|успеш|освобожд|разгром|взятие|капитуляц)'' AND result !~* ''вермахт'') AS victories
    FROM battle
    GROUP BY EXTRACT(MONTH FROM end_date)::int
)
SELECT am.month_num,
       am.month_name,
       COALESCE(mb.total_battles, 0)::int AS total_battles,
       COALESCE(ROUND(mb.victories * 100.0 / NULLIF(mb.total_battles, 0), 1)::float, 0.0) AS win_percentage
FROM all_months am
LEFT JOIN monthly_battles mb ON am.month_num = mb.month_num
ORDER BY am.month_num;',
    expected_result = '{"columns": ["month_num", "month_name", "total_battles", "win_percentage"], "data": [[1, "January", 3, 33.3], [2, "February", 4, 50.0], [3, "March", 2, 0.0], [4, "April", 2, 50.0], [5, "May", 5, 60.0], [6, "June", 2, 0.0], [7, "July", 1, 0.0], [8, "August", 3, 66.7], [9, "September", 2, 50.0], [10, "October", 3, 33.3], [11, "November", 0, 0.0], [12, "December", 3, 33.3]], "row_count": 12}'::jsonb,
    tags = ARRAY['cte', 'calendar', 'hard']::varchar[]
WHERE task_global_id = 83;
